insert into public.news (id, title, excerpt, content, image_url, image_alt, publish_date, tags, is_archived, is_published, created_at, updated_at) values
  ('69731c4aba95732f90893ca4', 'Welcome to Our Growing DigiGreenTT Group Network', 'FITTER-EU welcomes ten new DigiGreenTT Group to our network, expanding opportunities for cross-project collaboration on fair transitions.', 'We are delighted to welcome ten Horizon Europe projects to the FITTER-EU DigigreenTT Project Network. This diverse group brings expertise across just transition, digital inclusion, green skills, and policy development.

## New Network Members

Our network now includes projects such as, ST4TE, Greenpaths, Twin Synergies, and others who share our commitment to ensuring Europe''s twin transition is fair and inclusive for all.

## Collaboration Opportunities

With this expanded network, we see significant opportunities for:

- Cross-project knowledge exchange on methodologies and tools
- Joint stakeholder engagement activities
- Collaborative publications addressing common challenges
- Shared dissemination and outreach

## Join Us

If your Horizon Europe project works on related themes and you''d like to join our network, visit the Collaborate page to apply.

## Learn More

Visit the Sister Projects page to explore the full network and learn about each project''s focus and activities.', 'https://images.unsplash.com/photo-1559136555-9303baea8ebd?w=800&q=80', 'Wind turbines representing green transition', '2026-01-05', array['Network', 'Partnerships']::text[], true, true, '2026-01-23 06:59:22.455000+00', '2026-01-23 06:59:22.455000+00'),
  ('69731c4aba95732f90893ca2', 'TFC Launches DigiGreenTT Cluster Engagement Platform', 'A new dedicated platform for cross-project collaboration between Horizon Europe projects working on fair twin transitions is now live.', 'We are pleased to announce the launch of the DigiGreenTT Cluster Engagement platform, TFCENGAGE.com, designed to facilitate collaboration and knowledge sharing between Horizon Europe projects focused on fair, inclusive green and digital transitions.” If the article cannot be edited, add an editor''s correction note at the top stating that the platform was initiated by TFCENGAGE.com.

## Purpose

The platform serves as a central hub for:

- Connecting projects with complementary expertise
- Proposing and coordinating joint activities
- Sharing resources and best practices
- Building a community of practice around just transitions.

## Get Involved

Projects working on related themes are invited to join our network and explore collaboration opportunities. Visit the Collaborate page to submit your project or propose a joint activity.

## Contact

For more information, contact the FITTER-EU team at contact@tfcengage.com .', 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=800&q=80', 'Team collaboration meeting', '2026-01-15', array['Announcement', 'Collaboration']::text[], true, true, '2026-01-23 06:59:22.454000+00', '2026-04-14 10:42:24.411000+00'),
  ('3', 'DigiGreenTT Welcomes Prof. Christina Kakderi', 'We are delighted to  welcome  Prof. Kakderi as the first speaker for our autumn webinar series. Prof. Christina Kakderi,  is the coordinator of the ST4TE & PACT projects, joins us on 9th Sept 26 to present the #dashboard and #API built by ST4TE for the just measuring of the #twintransition.  ', 'Christina is Associate Professor at the School of Spatial Planning and Development, Aristotle University of Thessaloniki (AUTH), Greece, and a member of the URENIO Research Unit. Her research primarily focuses on regional innovation systems, smart cities, innovation policy, regional resilience, and the green, digital and twin transitions and it is the latter that the DigiGreenTT cluster webinar will focus on.

Christina coordinates the HorizonEurope project ST4TE (Strategies for Just and Equitable Twin Transitions in Europe) and the Horizon Europe project PACT. Both examine how Europe''s transitions can be made more inclusive and territorially balanced, which is of importance across many regions of Europe. Her recent research focuses on measuring regional green, digital and twin transitions and examining their implications for regional development and territorial cohesion and the webinar centred on this. 

It promises to be insightful!

DigiGreenTT webinar:
🗓️ 9th September 2026 │ 15:00–16:00 CET 

Registration link: 
https://lnkd.in/d-i4ZSGK

Register before 8th September, 17:00 CET to secure spot.', 'https://res.cloudinary.com/yxzbryel/image/upload/v1788470707/christina_kakderi.jpg', 'Team collaboration meeting', '2026-09-03', array['Announcement', 'Collaboration']::text[], false, true, '2026-09-03 06:59:22.454000+00', '2026-09-03 06:59:22.454000+00'),
  ('4', 'FITTER-EU Final Conference', '"From Insight to impact: Innovating for an Inclusive Twin Transition in Europe"', 'Registration is open for Fitter-EU Final Conference

"From Insight to impact: Innovating for an Inclusive Twin Transition in Europe"

Registration link: https://lnkd.in/d7DJ5eph

Fitter-EU''s final event brings together policymakers, researchers and practitioners for a day of discussion on the project''s findings and what should happen next.

Since 2024, the project has been researching how Europe''s green and digital transitions play out across different regions, sectors and groups, and what it would take for the benefits to reach further than they currently do. In Seville, we set out what that research shows and open it up for discussion.

The day is designed for exchange rather than presentation, so there will be time to question the conclusions and bring your own experience into the conversation.

📅 26 November 2026
📍 JRC Seville, Spain

Register today to secure your place.', 'https://res.cloudinary.com/yxzbryel/image/upload/v1788519030/Fitter-EU_final_conference.jpg', 'Team collaboration meeting', '2026-09-04', array['Announcement', 'Conference']::text[], true, true, '2026-09-04 06:59:22.454000+00', '2026-09-04 06:59:22.454000+00'),
  ('5', 'Leaving No One Behind', '"Shaping green and digital transition policies that work
for all people and territories in Europe"', 'The ST4TE Final Conference will examine how EU, national, regional and local policy can
respond to the uneven pathways of the twin transition.

Drawing on new evidence on technological specialisation, employment, skills, income, health
and regional vulnerability, the conference will consider where existing policy instruments are
working, where significant gaps remain, and how support can be better targeted at the people
and places most at risk of being left behind.

The conference will also launch ST4TE''s Twin Transition Inequalities Index and its
accompanying regional dashboard, and present the policy recommendations set out in the
project''s White Paper.

Sessions will bring together policymakers and officials from EU institutions and from national,
regional and local levels, alongside researchers, civil society representatives, social partners
and sister Horizon Europe projects.

Read the newly published <a href="https://www.espon.eu/sites/default/files/2026-10/tia-on-regional-skills-partnerships.pdf" target="_blank">Territorial Impact Assessment Report on Regional Skills Partnerships</a> for insights into how twin transition policies affect European regions.

 For further information on the agenda please use the link below: <a href="https://st4te.eu/events/st4te-final-conference" target="_blank">
ST4TE Final Conference | ST4TE? </a>', 'https://res.cloudinary.com/yxzbryel/image/upload/v1791283778/st4te.png', 'Team collaboration meeting', '2026-10-06', array['Announcement', 'Conference']::text[], true, true, '2026-09-04 06:59:22.454000+00', '2026-09-04 06:59:22.454000+00'),
  ('6', 'DigiGreenTT Cluster - Green & Digital Transition Webinar Series 1', 'On 9th September, the DigiGreenTT cluster webinar was held.', 'Titled "Beyond Green and Digital: 
Rethinking the Measurement of the Twin Transition" - a look at how the twin transition is measured across European regions, it was presented by Dr. Christina Kakderi (AUTH, ST4TE) and moderated by Mary Corbett (TFC, FITTER-EU). It is primarily based on the work and findings of the ongoing #HorizonEurope ST4TE project.

Dr. Karderi explained digital technologies are meant to reinforce each other, with digital tools making green solutions smarter and more controllable, while green objectives give digital technologies a purpose beyond efficiency alone. She illustrated this, sector by sector for instance, renewable energy generation combined with grid sensing and control produces smart grids capable of balancing intermittent supply; electrification combined with connectivity enables lower-emission connected mobility. The central question of the session was deceptively simple: is that combination actually happening and where, and for whom? ', 'https://res.cloudinary.com/yxzbryel/image/upload/v1791749463/digigreenCluster.jpg', null, '2026-10-09', array['Announcement', 'Conference']::text[], false, true, '2026-10-09 06:59:22.454000+00', '2026-10-09 06:59:22.454000+00'),
  ('7', 'GreenPath commuting - Final Conference', '📢 𝗧𝗵𝗲 𝗰𝗼𝘂𝗻𝘁𝗱𝗼𝘄𝗻 𝗶𝘀 𝗼𝗻! 𝗝𝘂𝘀𝘁 𝘁𝘄𝗼 𝘄𝗲𝗲𝗸𝘀 𝘂𝗻𝘁𝗶𝗹 𝘁𝗵𝗲 𝗚𝗿𝗲𝗲𝗻𝗣𝗔𝗧𝗛 𝗙𝗶𝗻𝗮𝗹 𝗖𝗼𝗻𝗳𝗲𝗿𝗲𝗻𝗰𝗲 𝗶𝗻 𝗕𝗿𝘂𝘀𝘀𝗲𝗹𝘀! 🌍', 'How can we make everyday commuting greener, healthier and more accessible for students and workers across Central Europe?

On 𝟮𝟭 𝗢𝗰𝘁𝗼𝗯𝗲𝗿 𝟮𝟬𝟮𝟲, the GreenPATH partnership will gather in Brussels to share the project''s achievements, explore innovative mobility solutions and discuss how local experiences can inspire long-term change in European urban areas.

🎯 What''s on the agenda?
🔹 𝗣𝗘𝗢𝗣𝗟𝗘 – Understanding commuter needs and encouraging sustainable mobility behaviours.
🔹 𝗗𝗔𝗧𝗔-𝗗𝗥𝗜𝗩𝗘𝗡 𝗧𝗢𝗢𝗟𝗦 – Exploring smart solutions to improve mobility management.
🔹 𝗚𝗢𝗩𝗘𝗥𝗡𝗔𝗡𝗖𝗘 – Strengthening cooperation between public authorities, employers and mobility actors.
🔹 𝗣𝗢𝗟𝗜𝗖𝗬 𝗧𝗥𝗔𝗡𝗦𝗙𝗘𝗥 – Turning pilot experiences into recommendations for sustainable commuting across Europe.

The conference will bring together representatives of European institutions, regional authorities, universities and mobility experts to exchange experiences and discuss the future of sustainable commuting.

📅 𝟮𝟭 𝗢𝗰𝘁𝗼𝗯𝗲𝗿 𝟮𝟬𝟮𝟲 | 𝟭𝟰:𝟬𝟬–𝟭𝟳:𝟯𝟬
📍 𝗘𝗺𝗶𝗹𝗶𝗮-𝗥𝗼𝗺𝗮𝗴𝗻𝗮 𝗥𝗲𝗴𝗶𝗼𝗻 𝗗𝗲𝗹𝗲𝗴𝗮𝘁𝗶𝗼𝗻 𝘁𝗼 𝘁𝗵𝗲 𝗘𝗨 | 𝗕𝗿𝘂𝘀𝘀𝗲𝗹𝘀
💚 𝗦𝘁𝘂𝗱𝗲𝗻𝘁𝘀 𝗮𝗻𝗱 𝘄𝗼𝗿𝗸𝗲𝗿𝘀 𝗮𝗿𝗲 𝗮𝘁 𝘁𝗵𝗲 𝗵𝗲𝗮𝗿𝘁 𝗼𝗳 𝗚𝗿𝗲𝗲𝗻𝗣𝗔𝗧𝗛. 𝗟𝗲𝘁''𝘀 𝘀𝗵𝗮𝗽𝗲 𝗮 𝗺𝗼𝗿𝗲 𝘀𝘂𝘀𝘁𝗮𝗶𝗻𝗮𝗯𝗹𝗲 𝗰𝗼𝗺𝗺𝘂𝘁𝗶𝗻𝗴 𝗳𝘂𝘁𝘂𝗿𝗲 𝘁𝗼𝗴𝗲𝘁𝗵𝗲𝗿!

👉 𝗗𝗶𝘀𝗰𝗼𝘃𝗲𝗿 𝘁𝗵𝗲 𝗽𝗿𝗼𝗴𝗿𝗮𝗺𝗺𝗲 𝗮𝗻𝗱 𝗿𝗲𝗴𝗶𝘀𝘁𝗲𝗿 <a href="https://lnkd.in/eZfebEDi" target="_blank">𝗵𝗲𝗿𝗲</a>', 'https://res.cloudinary.com/yxzbryel/image/upload/v1791752659/green-path.png', null, '2026-10-09', array['Announcement', 'Conference']::text[], false, true, '2026-10-09 06:59:22.454000+00', '2026-10-09 06:59:22.454000+00'),
  ('8', 'Driving the Green and Digital Transitions', 'Showcasing five projects at the Fitter-EU Final Conference! ', '<p>We are pleased to highlight an exciting opportunity for the DigiGreenTT members at the upcoming Fitter-EU Final Conference, taking place on 26 November 2026 at the Joint Research Centre (JRC) in Seville, Spain.</p>
<p>As Europe continues to navigate the twin transition, the interconnected green and digital transformations are reshaping industries, skills, education, and the future of work. While digitalisation creates opportunities for innovation, efficiency, and connectivity, the green transition calls for more sustainable practices, responsible resource use, and climate-conscious solutions. Addressing these two transitions together is essential to building a more sustainable, inclusive, and competitive future.</p>
<p>As part of the conference, a dedicated poster presentation session will provide DigiGreenTT members with an opportunity to showcase their projects, share their experiences, and discuss how their initiatives are tackling the challenges of the twin transition.</p>
<p><strong>Meet the projects contributing to the twin transition:</strong></p><ul><li>🔹 <a href="https://yconic.energypedia.info/wiki/We_make_learning_Yconic" target="_blank">YCONIC</a></li><li>🔹<a href="https://greenpaths.info" target="_blank"> GreenPaths</a></li><li>🔹 <a href="https://www.esira.eu" target="_blank">ESIRA</a></li><li>🔹 <a href="https://genesys-project.eu" target="_blank">Genesys</a></li><li>🔹 <a href="https://st4te.eu" target="_blank">ST4TE</a></li></ul><p>
Through this poster session, the projects will have a platform to present their work, highlight their approaches, and exchange ideas on the opportunities and challenges of combining digital innovation with environmental sustainability.</p>
<p>The session will also encourage dialogue, knowledge sharing, and collaboration among researchers, practitioners, stakeholders, and other participants working towards a greener and more digital Europe. By bringing these initiatives together, the conference offers an opportunity to explore different perspectives, share lessons learned, and identify potential synergies that can help accelerate the twin transition.</p>
<strong>Why does the twin transition matter?</strong><p>The twin transition is not simply about adopting new technologies or reducing environmental impact independently. It is about understanding how digital and green solutions can complement one another while ensuring that the transition remains practical, inclusive, and responsive to the needs of people, organisations, and communities.</p>
<p>The contributions of the DigiGreenTT members will bring these discussions to life by showcasing project experiences, innovative approaches, and insights that can inform wider conversations about sustainability, digital transformation, and future-ready skills.</p>
<p><strong>Date:</strong> 26 November 2026</p><p><strong>Venue:</strong> Joint Research Centre (JRC), Seville, Spain</p><p><strong>Event:</strong> Fitter-EU Final Conference</p><p><strong>Highlight:</strong> Poster presentations by DigiGreenTT members</p>
<p>We look forward to seeing these projects represented, learning more about their work, and 
connecting with others committed to advancing the green and digital transitions across Europe. </p>
<p>Together, let''s share knowledge, strengthen collaboration, and contribute to a more sustainable and digitally empowered future!</p>
<p>#FitterEU #DigiGreenTT #TwinTransition #GreenTransition #DigitalTransition #Sustainability #DigitalInnovation #EuropeanProjects #KnowledgeSharing</p>', 'https://res.cloudinary.com/yxzbryel/image/upload/v1792428472/fragment.png', null, '2026-10-19', array['Announcement', 'Conference']::text[], false, true, '2026-10-19 06:59:22.454000+00', '2026-10-19 06:59:22.454000+00'),
  ('9', 'Tackling Inequalities in the Green and Digital Transitions: Three EU Projects Collaborate on a New Policy White Paper', 'The green and digital transitions are transforming Europe, creating new opportunities while raising important questions about equality, inclusion. How can these transitions be made fairer, ensuring that their benefits reach everyone?', '<p>To explore this question, three EU projects, <a href="https://st4te.eu" target="_blank" rel="noopener noreferrer">ST4TE</a>, <a href="https://fitter-eu.com/en" target="_blank" rel="noopener noreferrer">FITTER-EU</a>, and <a href="https://readjust.eu/" target="_blank" rel="noopener noreferrer">READJUST</a>, are contributing to a joint policy white paper titled ‘Tackling Inequalities in the Green and Digital Transitions’. By bringing together their respective project experiences and expertise, the initiatives aim to develop policy recommendations that address inequalities and support more inclusive transitions across Europe.</p>
<strong>A shared effort, three project perspectives</strong>

<p>The first coordination meeting brought representatives from all three projects together to discuss the white paper’s content, development process, and the role each project will play in shaping the publication.</p>
<p>The meeting marked the beginning of a collaborative effort to bring together the projects’ distinct experiences and insights. By drawing on their respective contributions, the white paper will explore inequalities associated with the green and digital transitions and identify ways to address them through policy.</p>
<p><strong>The meeting was attended by</strong>:</p><ul><li><strong><a href="https://st4te.eu/" target="_blank" rel="noopener noreferrer">ST4TE</a>:</strong> Christina Kakderi, Aristotle University of Thessaloniki</li><li><strong><a href="https://fitter-eu.com/en" target="_blank" rel="noopener noreferrer">FITTER-EU</a>:</strong> Tom Flynn, TFC; Sara Clavero, TU Dublin; and Sushmita Puhan, TFC</li><li><strong><a href="https://readjust.eu/" target="_blank" rel="noopener noreferrer">READJUST</a>:</strong> Hannia Karime Gonzalez Urango, YAGHMA</li></ul>
<p>The representatives discussed how to coordinate their contributions and establish a shared direction for the white paper, while ensuring that each project’s specific experience is reflected in the final publication.</p>
<strong>From collaboration to policy action</strong><p>By bringing together insights from three distinct projects, the white paper aims to connect project experience with wider policy discussions on equality and inclusion. Its recommendations will seek to inform efforts to ensure that the benefits of Europe’s green and digital transitions are shared more fairly.</p>
<p>The initial meeting laid the foundation for this joint effort, bringing <a href="https://st4te.eu/" target="_blank" rel="noopener noreferrer">ST4TE</a>, <a href="https://fitter-eu.com/en" target="_blank" rel="noopener noreferrer">FITTER-EU</a>, and <a href="https://readjust.eu/" target="_blank" rel="noopener noreferrer">READJUST</a> together around a common goal: <em>helping shape green and digital transitions that are more inclusive and equitable for all.</em></p>', 'https://res.cloudinary.com/yxzbryel/image/upload/v1792429918/Picture_1.png', null, '2026-10-19', array['Announcement', 'Collaboration']::text[], false, true, '2026-10-19 07:59:22.454000+00', '2026-10-19 07:59:22.454000+00'),
  ('10', 'From Insight to Impact: Innovating for an inclusive twin transition in Europe', '', '<p>We’re delighted to welcome <a href="https://www.linkedin.com/in/davidesabbadinbrussels/" target="_blank" rel="noopener noreferrer">Davide Sabbadin</a>, Policy Manager for Energy at the <a href="https://www.linkedin.com/company/european-environmental-bureau/" target="_blank" rel="noopener noreferrer">European Environmental Bureau</a> (EEB), to the <a href="https://www.linkedin.com/company/fitter-eu/" target="_blank" rel="noopener noreferrer">Fitter-EU</a> Final Conference ''From Insight to Impact: Innovating for an inclusive twin transition in Europe'' in <a href="https://www.linkedin.com/search/results/all/?keywords=%23jrc&origin=HASH_TAG_FROM_FEED" target="_blank" rel="noopener noreferrer">#JRC</a>, Seville on 26 November 2026.</p>
<p>Davide Sabbadin has more than 20 years of experience in policy and campaigning, and his work centres on building decarbonisation. At the EEB he works on implementing the F-Gas Regulation and closely follows heating and cooling, energy efficiency, ETS2 and the Social Climate Fund. He also chairs the Cool Heating Coalition. Before joining the EEB, he spent several years at <a href="https://www.linkedin.com/company/legambiente/" target="_blank" rel="noopener noreferrer">Legambiente</a> in Italy working on energy efficiency, renewables, agriculture and the circular economy.</p>
<p>Davide''s work on the Social Climate Fund and ETS2 deals with who gains and who pays as Europe decarbonises. That’s the question at the centre of FITTER-EU: how to make the green and digital transitions fair and inclusive for everyone.</p>
<p>Places are limited, so <a href="https://forms.cloud.microsoft/pages/responsepage.aspx?id=yxdjdkjpX06M7Nq8ji_V2pgLeK1XPYZBgSLqWh07h4dUQlFaU1BQOEc2UEhVWlFLREY2WVMyOVkzVy4u&origin=QRCode&qrcodeorigin=presentation&route=shorturl", target="_blank" rel="noopener noreferrer">register</a> now and join us in Seville </p>
<p>26 November 2026<br>Joint Research Centre, Seville, Spain</p>
<p>More keynote speakers will be announced over the coming days. Stay tuned!</p>
<p><a href="https://www.linkedin.com/search/results/all/?keywords=%23fittereu&origin=HASH_TAG_FROM_FEED" target="_blank" rel="noopener noreferrer">#FITTEREU</a> <a href="https://www.linkedin.com/search/results/all/?keywords=%23justtransition&origin=HASH_TAG_FROM_FEED" target="_blank" rel="noopener noreferrer">#JustTransition</a> <a href="https://www.linkedin.com/search/results/all/?keywords=%23twintransition&origin=HASH_TAG_FROM_FEED" target="_blank" rel="noopener noreferrer">#TwinTransition</a> <a href="https://www.linkedin.com/search/results/all/?keywords=%23decarbonisation&origin=HASH_TAG_FROM_FEED" target="_blank" rel="noopener noreferrer">#Decarbonisation</a> <a href="https://www.linkedin.com/search/results/all/?keywords=%23horizoneurope&origin=HASH_TAG_FROM_FEED" target="_blank" rel="noopener noreferrer">#HorizonEurope</a> <a href="https://www.linkedin.com/search/results/all/?keywords=%23euresearch&origin=HASH_TAG_FROM_FEED" target="_blank" rel="noopener noreferrer">#EUResearch</a></p>', 'https://res.cloudinary.com/yxzbryel/image/upload/v1794402755/copy_of_fitter-eu_keynote_davide_sabbadin_website.png', null, '2026-11-11', array['Announcement', 'Collaboration']::text[], false, true, '2026-11-11 07:59:22.454000+00', '2026-11-11 07:59:22.454000+00');

insert into public.partners (id, name, acronym, country, logo_url, website, is_coordinator, description, sort_order, created_at, updated_at) values
  ('69731e2b7e5f702236fa3551', 'UNINOVA – Instituto de Desenvolvimento de Novas Tecnologias', 'UNINOVA', 'Portugal', null, null, false, 'UNINOVA is a research institute associated with NOVA University Lisbon, focused on new technologies and innovation. The institute conducts research in intelligent systems, robotics, and digital technologies for industrial and societal applications.', 10, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa3549', 'TFCEngage.com', 'TFC', 'Ireland', null, null, false, 'TFC is a research and innovation consultancy specialising in EU-funded project coordination, stakeholder engagement, and dissemination strategies. TFC supports projects across climate action, digital inclusion, and social innovation.', 2, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa354a', 'Smart Venice Srl', 'SV', 'Italy', null, null, false, 'Smart Venice is a research and consultancy organisation focused on sustainable urban development and smart city solutions. The organisation develops innovative approaches to environmental monitoring and citizen engagement in transition processes.', 3, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa354f', 'Székely Family & Co. Nonprofit Ltd.', 'SFC', 'Hungary', null, null, false, 'SFC is a non-profit organisation dedicated to community development and social innovation in Central and Eastern Europe. The organisation focuses on participatory approaches to regional transition challenges and capacity building for vulnerable communities.', 8, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa3550', 'Fondazione Giacomo Brodolini Srl SB', 'FGB', 'Italy', null, null, false, 'FGB is a research foundation specialising in labour market studies, social policy analysis, and inclusive economic development. The foundation provides evidence-based research to support fair transition policies and social cohesion across Europe.', 9, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa354b', 'AITEC Asesores Internacionales SRL', 'AITEC', 'Spain', null, null, false, 'AITEC is an international consultancy firm providing expertise in project management, policy analysis, and capacity building for European projects. AITEC specialises in supporting regional development and transition strategies.', 4, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa354d', 'Women Engage for a Common Future e.V.', 'WECF', 'Germany', null, null, false, 'WECF is an international network of environmental and women''s organisations working towards gender-just and sustainable transitions. WECF advocates for inclusive climate and environmental policies that address social equity and gender perspectives.', 6, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa354e', 'Universidad Complutense de Madrid', 'UCM', 'Spain', null, null, false, 'UCM is one of the oldest universities in Europe and a leading Spanish research institution. The university conducts interdisciplinary research in social sciences, environmental studies, and policy analysis with focus on sustainable development.', 7, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa354c', 'Fundació Eurecat', 'EURECAT', 'Spain', null, null, false, 'EURECAT is a leading applied research and technology centre in Catalonia. The organisation conducts research in digital technologies, industrial systems, and sustainability, with emphasis on technology transfer and innovation for societal challenges.', 5, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00'),
  ('69731e2b7e5f702236fa3548', 'Technological University Dublin', 'TU Dublin', 'Ireland', null, null, true, 'TU Dublin is Ireland''s first technological university, established in 2019. The university conducts research across sustainability, digital transformation, and social innovation, with a focus on evidence-based policy development for inclusive transitions.', 1, '2026-01-23 07:07:23.151000+00', '2026-01-23 07:07:23.151000+00');

insert into public.sister_projects (id, name, description, website, logo_url, status, tags, contact_name, contact_email, is_featured, featured_only, is_coordinator, belongs_to_project, sort_order, created_at, updated_at) values
  ('69dce7d5542ee9069202b57f', 'ESIRA', 'Empowering Social Innovation for Resilient Areas – supporting communities in transition through social innovation and inclusive approaches to green and digital change.', 'https://www.esira.eu', null, 'Onboard', array['Inclusion', 'Just Transition', 'Research']::text[], null, null, false, false, false, null, 13, '2026-04-13 12:55:49.887000+00', '2026-04-13 13:17:08.387000+00'),
  ('69731c4aba95732f90893c9a', 'TWIN RD', 'Research and development for twin transition policies that ensure fair outcomes for workers and communities.', 'https://www.twinrd.eu/', null, 'Onboard', array['Research', 'Just Transition', 'Policy']::text[], null, null, false, false, false, null, 7, '2026-01-23 06:59:22.441000+00', '2026-01-23 06:59:22.441000+00'),
  ('69731c4aba95732f90893c98', 'Greenpaths', 'Exploring pathways to green transitions that prioritise social inclusion and equitable outcomes across European regions.', 'https://greenpaths.info/', null, 'Onboard', array['Green', 'Inclusion', 'Just Transition']::text[], null, null, false, false, false, null, 5, '2026-01-23 06:59:22.441000+00', '2026-01-23 06:59:22.441000+00'),
  ('69731c4aba95732f90893c94', 'FITTER-EU', 'Fair, Inclusive Twin Transition for European Regions – advancing social justice to reduce inequality in Europe''s green and digital transitions.', 'https://fitter-eu.com', null, 'Onboard', array['Just Transition', 'Inclusion', 'Digital', 'Green', 'Policy']::text[], null, null, true, false, false, null, 1, '2026-01-23 06:59:22.441000+00', '2026-01-23 06:59:22.441000+00'),
  ('69731c4aba95732f90893c95', 'TFCENGAGE.com', 'Initiator and coordinator of the DigiGreenTT Cluster, delivered through TFCENGAGE.com, specialising in EU-funded research coordination and stakeholder engagement.', 'https://tfcengage.com', null, 'Onboard', array['Research', 'Policy']::text[], null, null, true, false, true, null, 2, '2026-01-23 06:59:22.441000+00', '2026-04-13 12:56:58.505000+00'),
  ('69731c4aba95732f90893c97', 'ST4TE', 'Supporting territories in achieving twin transition through evidence-based policy tools and multi-stakeholder engagement.', 'https://st4te.eu/', null, 'Onboard', array['Digital', 'Green', 'Policy']::text[], null, null, false, false, false, null, 4, '2026-01-23 06:59:22.441000+00', '2026-01-23 06:59:22.441000+00'),
  ('69731c4aba95732f90893c99', 'Twin Synergies', 'Leveraging synergies between green and digital transitions to maximise socio-economic benefits and minimise inequalities.', 'https://www.twinsynergies.net/', null, 'Onboard', array['Digital', 'Green', 'Skills']::text[], null, null, false, false, false, null, 6, '2026-01-23 06:59:22.441000+00', '2026-01-23 06:59:22.441000+00'),
  ('69731c4aba95732f90893c9e', 'WISE', 'Working towards inclusive and sustainable economies through evidence-based transition frameworks.', 'http://www.wise-project.eu/', null, 'Onboard', array['Inclusion', 'Green', 'Skills']::text[], null, null, false, false, false, null, 11, '2026-01-23 06:59:22.441000+00', '2026-01-23 06:59:22.441000+00'),
  ('69731c4aba95732f90893c9d', 'Genesys', 'Generating systemic solutions for fair transitions through multi-disciplinary research and policy engagement.', 'https://genesys-project.eu/', null, 'Onboard', array['Research', 'Policy', 'Just Transition']::text[], null, null, false, false, false, null, 10, '2026-01-23 06:59:22.441000+00', '2026-01-23 06:59:22.441000+00');

