  ('3', 'FITTER-EU Deliverable D3.1', 'Deliverable', 'Report on vulnerabilities mapping under the baseline scenario', 'https://drive.google.com/file/d/16ZOmJnKKON2d-XHVlfsj765MxDUcBXIr/view?usp=drive_link', '2025-03-17', 'Olga Kolotouchkina, Paloma Piqueiras (UCM)', null, null, 'FITTER', true, false),
  ('4', 'FITTER-EU Deliverable D2.2', 'Deliverable', 'Embedding social justice in twin transition research: Concepts, definitions and methodological approach', 'https://drive.google.com/file/d/1LXRmfkmoQUf9cn9kpnFl3gqViSyXkOmY/view?usp=drive_link', '2025-03-17', 'ONóirín MacNamara, Alicja Bobek, Sara Clavero', null, null, 'FITTER', true, false),
