  ('6', 'FITTER-EU Deliverable D2.4', 'Deliverable', 'Mapping the governance of the twin-transition', 'https://drive.google.com/file/d/1FY66_d_TyxK8iKP49PzJaz4YZSDsRXLc/view?usp=drive_link', '2025-11-06', 'Silvia Sansonetti and Roberta Cupertino (FGB)', null, null, 'FITTER', true, false),
